mapper.select:
select id,account,name,auth_status,disabled,dict_platform from ( SELECT id,account,name,auth_status,disabled,dict_platform FROM shop_info si WHERE si.is_deleted=FALSE
${params.permissionSql}
and ((si.account = #{params.searchKeyword}) or (si.id = #{params.searchKeyword}) or si.name ilike concat('%', #{params.searchKeyword}::text ,'%'))
and si.dict_area_code = #{params.dictAreaCode}
and si.dict_platform = #{params.dictPlatform}
and si.id in
(#{item})
order by
case when si.name ILIKE concat(#{params.searchKeyword}::text,'%') THEN 1 when si.name ILIKE concat('%',#{params.searchKeyword}::text) THEN 2 when si.name ILIKE concat('%',#{params.searchKeyword}::text,'%') THEN 3 end , si.name,
si.disabled asc ) shop

select dict_area_code from shop_info si
si.is_deleted = false
and si.dict_area_code = #{params.searchKeyword}
and si.dict_platform = #{params.dictPlatform}
group by dict_area_code order by dict_area_code desc

select si.id as shopId , si.name as shopName, si.auth_status as authStatus, si.dict_platform as dictPlatform from shop_info si where ${params.sqlMap.default} and si.is_deleted = false and si.disabled = false
and si.id in
#{item}

select si.*
from shop_info si
where si.is_deleted = false


    ${permissionSql}


    AND  si.dict_platform IN

        #{platform}

select id, name, account, auth_status as authStatus, sales_org_id as salesOrgId, sales_org_name as salesOrgName, dict_platform as dictPlatform, disabled from shop_info where is_deleted = false
and name in
#{name}
${permissionSql}

select si.id as id, si.name as name, si.id as shopId, si.name as shopName, si.dict_platform as dictPlatform, si.disabled as disabled, si.dict_country_code as countryId, si.country_name as countryName, si.warehouse_id as warehouseId, si.warehouse_name as warehouseName, si.type as type, 'true' as hasWarehouseAuth from shop_info si where si.is_deleted = false
${permissionSql}
and si.dict_platform = #{dictPlatform}
